CREATE TABLE `html_craft` (
  `action` varchar(100) CHARACTER SET utf8 COLLATE utf8_bin NOT NULL,
  `npcid` int(10) NOT NULL DEFAULT '0',
  `note` varchar(255) DEFAULT '',
  `craft_itemid` varchar(255) NOT NULL DEFAULT '40308',
  `craft_count` varchar(255) NOT NULL DEFAULT '0',
  `material` varchar(255) NOT NULL,
  `material_count` varchar(255) NOT NULL,
  `success_html` varchar(45) DEFAULT '',
  `fail_html` varchar(45) DEFAULT '',
  `isInputable` int(1) NOT NULL DEFAULT '0',
  PRIMARY KEY (`action`,`npcid`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

